{
  "abilities": [
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "Orianna's basic attacks generate a stack of Clockwork Winding for 4 seconds, refreshing on subsequent attacks and stacking up to 2 times. All stacks are lost when attacking a new enemy.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "Stacks expire, refresh on subsequent attacks, have a cap, and reset when attacking a different enemy."
        },
        {
          "citations": [
            {
              "quote": "The attacks do not deal the bonus damage against structures.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "The bonus attack damage excludes structures."
        },
        {
          "citations": [
            {
              "quote": "The Ball attaches to Orianna when she approaches it, and snaps back to her when she moves too far away.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "Orianna retrieves the Ball by approaching it; exceeding its leash returns it to her."
        },
        {
          "citations": [
            {
              "quote": "The Ball incurs a 0.01-second global cooldown on all of her abilities when she casts any ability.",
              "source_id": "wiki:P"
            },
            {
              "quote": "The Ball will not incur its global cooldown from a Command: Protect cast that is used on a target already attached to it.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "Casting abilities briefly locks other abilities, with an exception for E cast on the Ball's current carrier."
        },
        {
          "citations": [
            {
              "quote": "Runaan's Hurricane's extra bolts will cause Clockwork Winding to reset its stacks, as she hits targets other than her latest one on-hit.(unexpected)",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "The Wiki reports that Runaan's Hurricane extra bolts reset stacks by hitting other targets."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Orianna's Attacks deal additional magic damage.",
              "source_id": "riot:P"
            },
            {
              "quote": "Clockwork Winding: Orianna's basic attacks deal bonus magic damage, increased for each stack.",
              "source_id": "wiki:P"
            }
          ],
          "id": "P.bonus_magic_damage",
          "summary": "Basic attacks deal bonus magic damage to eligible targets."
        },
        {
          "citations": [
            {
              "quote": "This damage increases the more Orianna Attacks the same target.",
              "source_id": "riot:P"
            },
            {
              "quote": "Orianna's basic attacks generate stacks of Clockwork Winding, which refresh on subsequent hits and stack up to a cap.",
              "source_id": "wiki:P"
            }
          ],
          "id": "P.repeated_target",
          "summary": "Repeated attacks against the same target increase the bonus damage up to a cap."
        }
      ],
      "slot": "P",
      "unsupported_claims": [
        "The attack damage increase stacks indefinitely.",
        "Unverified visual frames establish current-client or skin-specific behavior."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "deals less damage to subsequent targets",
              "source_id": "riot:Q"
            },
            {
              "quote": "reduced to 70% against those hit beyond the first.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Targets beyond the first take reduced damage."
        },
        {
          "citations": [
            {
              "quote": "dealing magic damage to enemies it passes through and nearby enemies upon arrival.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Damage also affects nearby enemies at the arrival location."
        },
        {
          "citations": [
            {
              "quote": "If The Ball is currently on Orianna herself, Command: Attack will have it cast to fly at least 150 units if the player attempts to cast it closer.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Casting from Orianna has a minimum travel distance."
        },
        {
          "citations": [
            {
              "quote": "Orianna cannot use Command: Protect while The Ball is in transit with Command: Attack but she may buffer Command: Dissonance and Command: Shockwave to cast once it has reached the location.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "During Q travel, E is unavailable; W and R can be buffered for arrival."
        },
        {
          "citations": [
            {
              "quote": "The Ball will remain at the target location until Orianna retrieves it or if she goes beyond its leash range.",
              "source_id": "wiki:Q"
            },
            {
              "quote": "The Ball will also never exceed its leash range regardless of target direction.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Ball placement remains subject to retrieval and leash limits."
        },
        {
          "citations": [
            {
              "quote": "The Ball does not grant sight while in flight, but the sound effect of striking an enemy is audible through the Fog of War.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Travel grants no sight, although hit sounds are audible through fog of war."
        },
        {
          "citations": [
            {
              "quote": "PENDING FOR TEST: The Ball will drop to the ground upon colliding with Yasuo's Wind Wall but not with Braum's Unbreakable.",
              "source_id": "wiki:Q"
            },
            {
              "quote": "Samira's Blade Whirl?",
              "source_id": "wiki:Q"
            }
          ],
          "status": "uncertain",
          "summary": "Q interactions with these projectile-blocking abilities are unresolved in the packet."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Orianna commands her Ball to fire toward a target location",
              "source_id": "riot:Q"
            },
            {
              "quote": "Orianna commands The Ball to fly to the target location and remain there",
              "source_id": "wiki:Q"
            }
          ],
          "id": "Q.position_ball",
          "summary": "Sends the Ball to a chosen location, where it remains subject to retrieval and leash limits."
        },
        {
          "citations": [
            {
              "quote": "dealing magic damage to targets along the way",
              "source_id": "riot:Q"
            },
            {
              "quote": "dealing magic damage to enemies it passes through and nearby enemies upon arrival.",
              "source_id": "wiki:Q"
            }
          ],
          "id": "Q.magic_damage",
          "summary": "The moving Ball deals magic damage to enemies along its path."
        }
      ],
      "slot": "Q",
      "unsupported_claims": [
        "Q definitely drops at Yasuo's Wind Wall but passes Braum's Unbreakable.",
        "A specific interaction with Samira's Blade Whirl is established.",
        "Q grants vision while traveling."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "The pulse leaves behind an electric field that last 3 seconds, granting bonus movement speed to Orianna and her allies when they move within. Enemies that move within the field are slowed by the same amount, decaying over 2 seconds after leaving.",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "The field lasts briefly, includes Orianna among its speed recipients, and the enemy slow decays after leaving."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Orianna commands her Ball to release a pulse of energy, dealing magic damage around it.",
              "source_id": "riot:W"
            },
            {
              "quote": "Orianna commands The Ball to emit an electric pulse that deals magic damage to nearby enemies.",
              "source_id": "wiki:W"
            }
          ],
          "id": "W.pulse_damage",
          "summary": "The Ball emits a pulse that deals magic damage to nearby enemies."
        },
        {
          "citations": [
            {
              "quote": "This leaves a field behind that speeds up allies and slows enemies.",
              "source_id": "riot:W"
            },
            {
              "quote": "which slows enemies and grants bonus movement speed to Orianna and allied champions.",
              "source_id": "wiki:W"
            }
          ],
          "id": "W.ally_speed",
          "summary": "The lingering field speeds up Orianna and allied champions within it."
        },
        {
          "citations": [
            {
              "quote": "This leaves a field behind that speeds up allies and slows enemies.",
              "source_id": "riot:W"
            },
            {
              "quote": "Enemies that move within the field are slowed by the same amount",
              "source_id": "wiki:W"
            }
          ],
          "id": "W.enemy_slow",
          "summary": "The lingering field slows enemies within it."
        }
      ],
      "slot": "W",
      "unsupported_claims": [
        "The lingering field repeatedly deals damage.",
        "Arena-specific scaling establishes the standard-mode damage scaling."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "fly to herself or the target allied champion and attach itself to the target",
              "source_id": "wiki:E"
            },
            {
              "quote": "granting the target a shield for 2.5 seconds upon arrival.",
              "source_id": "wiki:E"
            },
            {
              "quote": "Orianna gains Command: Protect's bonus resistances whenever The Ball is attached to her (even if she didn't self-cast).",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "E can target Orianna herself. Its shield begins on arrival, and Orianna receives the resistances whenever the Ball is attached to her."
        },
        {
          "citations": [
            {
              "quote": "Orianna cannot cast her other abilities while the The Ball is moving to the target with Command: Protect.",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "Other abilities cannot be cast during E travel."
        },
        {
          "citations": [
            {
              "quote": "The Ball will remain where Command: Protect's target ally died or, if they died or became untargetable before The Ball reaches them, it will instead snap back to Orianna.",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "An attached ally's death leaves the Ball at their death location; death or untargetability before arrival returns it to Orianna."
        },
        {
          "citations": [
            {
              "quote": "The Ball will return to Orianna if Command: Protect's target ally moves too far away from her (The Ball will always respect its leash range, which is increased by 100 when attached to allied champions).",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "An allied carrier remains subject to a leash, with a larger leash allowance than an unattached Ball."
        },
        {
          "citations": [
            {
              "quote": "The Ball will join Command: Protect's target ally in stealth if they are affected by it when Orianna targets them.",
              "source_id": "wiki:E"
            },
            {
              "quote": "The Ball snaps back to Orianna upon being intercepted by projectile-blocking effects.",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "The Ball joins an already stealthed target in stealth and returns to Orianna if intercepted by projectile-blocking effects."
        },
        {
          "citations": [
            {
              "quote": "The Ball does not grant sight while in flight, but the sound effect of striking an enemy is audible through the Fog of War.",
              "source_id": "wiki:E"
            },
            {
              "quote": "Command: Protect has a forgiveness radius of 175 units.",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "Travel grants no sight but can provide audible hit feedback; the Wiki also specifies a targeting forgiveness radius."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Orianna commands her Ball to attach to an allied champion, Shielding them",
              "source_id": "riot:E"
            },
            {
              "quote": "Orianna commands The Ball to fly and attach to herself or the target allied champion",
              "source_id": "wiki:E"
            },
            {
              "quote": "shielding the target for a short time.",
              "source_id": "wiki:E"
            }
          ],
          "id": "E.attach_shield",
          "summary": "Sends the Ball to attach to Orianna or an allied champion and shield the recipient on arrival."
        },
        {
          "citations": [
            {
              "quote": "dealing magic damage to any enemies it passes through on the way.",
              "source_id": "riot:E"
            },
            {
              "quote": "dealing magic damage to enemies it passes through",
              "source_id": "wiki:E"
            }
          ],
          "id": "E.path_damage",
          "summary": "The Ball deals magic damage to enemies it passes through."
        },
        {
          "citations": [
            {
              "quote": "the Ball grants additional Armor and Magic Resist to the champion it is attached to.",
              "source_id": "riot:E"
            },
            {
              "quote": "Passive: The Ball grants bonus armor and bonus magic resistance to the unit it is attached to.",
              "source_id": "wiki:E"
            }
          ],
          "id": "E.carrier_resistances",
          "summary": "The attached Ball protects its carrier with bonus armor and magic resistance."
        }
      ],
      "slot": "E",
      "unsupported_claims": [
        "E can target any allied unit, including minions.",
        "The shield is granted before the Ball arrives.",
        "The bonus resistances persist after the Ball leaves its carrier."
      ]
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "briefly stunning and pulling them inward.",
              "source_id": "wiki:R"
            },
            {
              "quote": "Displacement immunity will not resist the application of the stun.",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "R also briefly stuns; displacement immunity does not prevent that stun."
        },
        {
          "citations": [
            {
              "quote": "pulls them over 325 units, though not through terrain.",
              "source_id": "wiki:R"
            },
            {
              "quote": "Command: Shockwave tosses enemies a set distance (those on the edge of the flinging area will be tossed to the center while those close to the middle will go over The Ball towards the edge) and can send them through walls.",
              "source_id": "wiki:R"
            }
          ],
          "status": "disputed",
          "summary": "Terrain traversal is internally contradictory: the active description excludes it, while the notes allow passage through walls. The general displacement remains supported."
        },
        {
          "citations": [
            {
              "quote": "those on the edge of the flinging area will be tossed to the center while those close to the middle will go over The Ball towards the edge",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "The displacement is a set-distance toss; enemies near the center can pass over the Ball rather than stop at its center."
        },
        {
          "citations": [
            {
              "quote": "This ability will cast from wherever the caster is at the end of the cast time.",
              "source_id": "wiki:R"
            },
            {
              "quote": "Command: Shockwave will cast from wherever the unit the The Ball is attached to is at the end of the cast time, even if the unit exceeds max tether range.",
              "source_id": "wiki:R"
            }
          ],
          "status": "uncertain",
          "summary": "The notes describe end-of-cast positioning ambiguously, referring both to the caster and to the attached carrier. The precise general origin rule is unclear."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Orianna commands her Ball to unleash a shockwave, dealing magic damage",
              "source_id": "riot:R"
            },
            {
              "quote": "Orianna commands The Ball to unleash a shockwave that deals magic damage to nearby enemies",
              "source_id": "wiki:R"
            }
          ],
          "id": "R.area_damage",
          "summary": "The Ball unleashes a shockwave that deals magic damage to nearby enemies."
        },
        {
          "citations": [
            {
              "quote": "launching nearby enemies towards the Ball after a short delay.",
              "source_id": "riot:R"
            },
            {
              "quote": "briefly stunning and pulling them inward.",
              "source_id": "wiki:R"
            }
          ],
          "id": "R.delayed_displacement",
          "summary": "After a short delay, the shockwave displaces nearby enemies toward the Ball."
        }
      ],
      "slot": "R",
      "unsupported_claims": [
        "R always deposits every affected enemy exactly at the Ball's center.",
        "R definitively can or cannot move enemies through terrain.",
        "Displacement immunity prevents R's stun.",
        "Arena-specific cooldowns establish standard-mode cooldowns."
      ]
    }
  ]
}
